from pathlib import Path
import ast

ROOT=Path.cwd()
SUB=ROOT/"qseries_v2"/"oracle_execution"
SUB.mkdir(parents=True,exist_ok=True)

MOD=SUB/"oracle_031_saved_alt_atomic_shadow_cutover.py"
TEST=ROOT/"test_oracle_031_saved_alt_atomic_shadow_cutover.py"
RUN=ROOT/"run_oracle_031_saved_alt_atomic_shadow_cutover.py"

MODULE_SOURCE='\nfrom __future__ import annotations\nfrom pathlib import Path\n\nfrom qseries_v2.oracle_strategy_intelligence.solana_money import qsb059_gav_reverse_atomic as q59\nfrom qseries_v2.oracle_strategy_intelligence.solana_money.qarb_execution_engineering import qarb_087_two_second_compaction_liquidity_repair as q87\nfrom qseries_v2.solana_live_execution import qarb_097_official_meteora_sdk_executor as q97\n\nEXECUTION_AUTHORITY=False\nPAPER_ONLY=True\nREAL_MONEY_MOVED=False\nMAX_TX_BYTES=1232\n\n_ORIG_COMPOSE=q59.compose_reverse_candidates\n_ORIG_ATTEMPT=q59.attempt_candidate_simulations\n\ndef compose_with_token(user,token,pump_pool,meteora_pool,start_sol):\n    route=_ORIG_COMPOSE(user,token,pump_pool,meteora_pool,start_sol)\n    route=dict(route)\n    route["token"]=token\n    return route\n\ndef execution_route(route):\n    return {\n        "token":route.get("token"),\n        "start_lamports":int(route["start_lamports"]),\n        "pre_sim_net_lamports":int(route.get("pre_sim_net_lamports",0)),\n        "pre_sim_bps":float(route.get("pre_sim_bps",0.0)),\n        "base_alts":list(route.get("alts") or route.get("base_alts") or []),\n        "original_candidates":list(route.get("candidates") or route.get("original_candidates") or []),\n    }\n\ndef apply_saved_alt(root,route):\n    before=list(route["base_alts"])\n    result=q97._apply_saved_alt(Path(root),route)\n    if isinstance(result,dict):\n        route=result\n    after=list(route.get("base_alts") or [])\n    return route,before,after\n\ndef saved_alt_attempt_candidate_simulations(user,kp,route,blockhash):\n    x=execution_route(route)\n    token=x.get("token")\n    x,before,after=apply_saved_alt(Path.cwd(),x)\n\n    print("[ORACLE031_ALT] token=%s base_alts=%d saved_alts=%d"%(\n        str(token)[:12],len(before),len(after)\n    ),flush=True)\n\n    candidates=list(q87.repaired_candidates(x))\n    rows=[]\n\n    for candidate in candidates:\n        name=str(candidate.get("name",""))\n\n        # Preserve QARB-097 live safety rule: helper-stripped shell is not executable authority.\n        if "PUMP_METEORA_ONLY" in name:\n            row={\n                "name":name,\n                "compiled":False,\n                "bytes":None,\n                "error":"LIVE_REJECT_HELPER_STRIPPED_PUMP_SHELL",\n                "profitable":False,\n            }\n            rows.append(row)\n            print("[ORACLE031_CANDIDATE] %s REJECT=%s"%(\n                name,row["error"]\n            ),flush=True)\n            continue\n\n        row=q87.simulate_candidate(\n            user,\n            kp,\n            x,\n            candidate,\n            [list(x.get("base_alts") or [])],\n            blockhash,\n        )\n        rows.append(row)\n\n        print("[ORACLE031_CANDIDATE] %s compiled=%s bytes=%s alts=%s sim_err=%s pnl=%s bps=%s profitable=%s"%(\n            name,\n            row.get("compiled"),\n            row.get("bytes"),\n            row.get("alt_count"),\n            row.get("sim_err"),\n            row.get("sim_pnl_lamports"),\n            row.get("sim_bps"),\n            row.get("profitable"),\n        ),flush=True)\n\n        if (\n            row.get("compiled")\n            and int(row.get("bytes",MAX_TX_BYTES+1))<=MAX_TX_BYTES\n            and row.get("sim_err") is None\n            and row.get("profitable")\n        ):\n            return row,rows\n\n    return None,rows\n\ndef install():\n    q59.compose_reverse_candidates=compose_with_token\n    q59.attempt_candidate_simulations=saved_alt_attempt_candidate_simulations\n    return True\n\ndef run(seconds=300.0):\n    install()\n    from qseries_v2.oracle_execution import oracle_029_full_exact_pair_coverage_cutover as q29\n    print("[ORACLE-031] SAVED-ALT ATOMIC SHADOW CUTOVER",flush=True)\n    print("[ALT] QARB-097 saved ALT only; no Mriya lookup in hot path",flush=True)\n    print("[CANDIDATES] QARB-087 repaired ladder",flush=True)\n    print("[INPUT] ORACLE-028 exact-current positive handoff",flush=True)\n    print("[MAX_TX_BYTES] 1232",flush=True)\n    print("[BROADCAST] disabled",flush=True)\n    return q29.run(seconds=seconds)\n\nif __name__=="__main__":\n    raise SystemExit(run())\n'
TEST_SOURCE='\nimport inspect, unittest\nfrom unittest.mock import patch\nfrom qseries_v2.oracle_execution import oracle_031_saved_alt_atomic_shadow_cutover as q31\n\nclass T(unittest.TestCase):\n    def test_safety(self):\n        self.assertFalse(q31.EXECUTION_AUTHORITY)\n        self.assertTrue(q31.PAPER_ONLY)\n        self.assertFalse(q31.REAL_MONEY_MOVED)\n\n    def test_hot_path_has_no_mriya_lookup(self):\n        src=inspect.getsource(q31.saved_alt_attempt_candidate_simulations)\n        self.assertNotIn("recent_mriya_alt_keys",src)\n        self.assertNotIn("compile_signed",src)\n\n    def test_route_adapter(self):\n        r=q31.execution_route({\n            "token":"T",\n            "start_lamports":1000,\n            "pre_sim_net_lamports":20,\n            "pre_sim_bps":200.0,\n            "alts":["A"],\n            "candidates":[("FULL",[])],\n        })\n        self.assertEqual(r["token"],"T")\n        self.assertEqual(r["base_alts"],["A"])\n        self.assertEqual(r["original_candidates"],[("FULL",[])])\n\n    def test_saved_alt_return_or_mutation_supported(self):\n        route={"token":"T","base_alts":["A"],"original_candidates":[],"start_lamports":1}\n        def mutate(root,r):\n            r["base_alts"].append("B")\n            return None\n        with patch.object(q31.q97,"_apply_saved_alt",mutate):\n            out,before,after=q31.apply_saved_alt(".",route)\n        self.assertEqual(before,["A"])\n        self.assertEqual(after,["A","B"])\n        self.assertEqual(out["base_alts"],["A","B"])\n\n    def test_helper_stripped_shell_rejected(self):\n        route={\n            "token":"T","start_lamports":1000,\n            "pre_sim_net_lamports":10,"pre_sim_bps":100.0,\n            "alts":[],"candidates":[("PUMP_METEORA_ONLY",[])],\n        }\n        with patch.object(q31.q97,"_apply_saved_alt",lambda root,r:r), \\\n             patch.object(q31.q87,"repaired_candidates",lambda r:[\n                 {"name":"PUMP_METEORA_ONLY","instructions":[],"pump_optional_removed":0}\n             ]):\n            winner,rows=q31.saved_alt_attempt_candidate_simulations("U",None,route,"BH")\n        self.assertIsNone(winner)\n        self.assertEqual(rows[0]["error"],"LIVE_REJECT_HELPER_STRIPPED_PUMP_SHELL")\n\n    def test_no_broadcast(self):\n        src=inspect.getsource(q31)\n        self.assertNotIn("sendTransaction(",src)\n\nif __name__=="__main__":\n    unittest.main(verbosity=2)\n'
RUN_SOURCE='\nimport argparse\nfrom qseries_v2.oracle_execution.oracle_031_saved_alt_atomic_shadow_cutover import run\n\nif __name__=="__main__":\n    p=argparse.ArgumentParser()\n    p.add_argument("--seconds",type=float,default=300.0)\n    a=p.parse_args()\n    raise SystemExit(run(seconds=a.seconds))\n'

ast.parse(MODULE_SOURCE)
ast.parse(TEST_SOURCE)
ast.parse(RUN_SOURCE)

MOD.write_text(MODULE_SOURCE.lstrip(),encoding="utf-8")
TEST.write_text(TEST_SOURCE.lstrip(),encoding="utf-8")
RUN.write_text(RUN_SOURCE.lstrip(),encoding="utf-8")

print("[PASS] ORACLE-031 saved-ALT atomic shadow cutover installed")
print("[PATCH] q59 compose route gains token context")
print("[PATCH] q59 atomic simulation uses QARB-097 saved ALT + QARB-087 repaired candidates")
print("[HOT_PATH] recent_mriya_alt_keys=DISABLED")
print("[SHELL] PUMP_METEORA_ONLY remains rejected for execution authority")
print("[BROADCAST] disabled")
